        store.insert("cgt-003", "test prompt", "standard").unwrap();
        store
            .update_status("cgt-003", "succeeded", Some("https://example.com/v.mp4"))
            .unwrap();

        let records = store.list(10, None).unwrap();
        assert_eq!(records[0].status, "succeeded");
