use anyhow::{Context, Result};
use std::process::Command;

use super::upload;

/// Probe the duration of a video file in seconds using ffprobe.
pub fn probe_duration(path: &str) -> Result<f64> {
    let output = Command::new("ffprobe")
        .args([
            "-v",
            "error",
            "-show_entries",
            "format=duration",
            "-of",
            "csv=p=0",
            path,
        ])
        .output()
        .context("failed to run ffprobe — is ffmpeg installed? (brew install ffmpeg)")?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        anyhow::bail!("ffprobe failed: {stderr}");
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let duration_str = stdout.trim();
    duration_str
        .parse::<f64>()
        .with_context(|| format!("failed to parse ffprobe duration output: '{duration_str}'"))
}

/// Trim a video from the end, keeping the last `keep_secs` seconds.
/// First tries stream copy (-c copy) for speed; falls back to re-encode on failure.
pub fn trim_from_end(input: &str, output: &str, keep_secs: f64) -> Result<()> {
    // Attempt 1: stream copy (fast, lossless)
    let result = Command::new("ffmpeg")
        .args([
            "-y",
            "-sseof",
            &format!("-{keep_secs}"),
            "-i",
            input,
            "-c",
            "copy",
            output,
        ])
        .output()
        .context("failed to run ffmpeg — is ffmpeg installed? (brew install ffmpeg)")?;

    if result.status.success() {
        return Ok(());
    }

    // Attempt 2: re-encode to ensure clean cut points
    // First probe total duration to compute start offset
    let total = probe_duration(input)?;
    let start = (total - keep_secs).max(0.0);

    let result2 = Command::new("ffmpeg")
        .args([
            "-y",
            "-ss",
            &format!("{start}"),
            "-i",
            input,
            "-t",
            &format!("{keep_secs}"),
            "-c:v",
            "libx264",
            "-preset",
            "fast",
            "-crf",
            "23",
            "-c:a",
            "aac",
            output,
        ])
        .output()
        .context("failed to run ffmpeg for re-encode")?;

    if !result2.status.success() {
        let stderr = String::from_utf8_lossy(&result2.stderr);
        anyhow::bail!("ffmpeg trim failed (both copy and re-encode): {stderr}");
    }

    Ok(())
}

/// Prepare a source video for extend: probe duration, trim if too long, upload.
///
/// If the input is already an HTTP(S) URL, it is returned as-is (no probing/trimming).
/// If the video duration exceeds `max_duration`, it is trimmed from the end
/// to `max_duration` seconds. The result is uploaded as a base64 data URI.
pub fn prepare_source_video(input: &str, max_duration: u8) -> Result<String> {
    // URLs are passed through directly — can't probe or trim remotely
    if input.starts_with("http://") || input.starts_with("https://") || input.starts_with("asset://") {
        return Ok(input.to_string());
    }

    let duration = probe_duration(input)?;

    if duration <= max_duration as f64 {
        return upload::resolve_file_ref(input);
    }

    // Trim: keep the last max_duration seconds
    let trimmed_path = format!("{input}.seedance_trimmed.mp4");
    trim_from_end(input, &trimmed_path, max_duration as f64)?;

    let url = upload::resolve_file_ref(&trimmed_path);

    // Clean up temp file (best-effort)
    let _ = std::fs::remove_file(&trimmed_path);

    url
}

