mod upload_tests {
    use seedance_cli::core::upload;

    #[test]
    fn http_url_passes_through() {
        let url = "https://example.com/image.jpg";
        assert_eq!(upload::resolve_file_ref(url).unwrap(), url);
    }

    #[test]
    fn http_insecure_url_passes_through() {
