            "status": "succeeded",
            "video_url": "https://example.com/v.mp4",
            "usage": {"completion_tokens": 102960, "total_tokens": 102960}
        }"#;
        let resp: TaskResponse = serde_json::from_str(json).unwrap();
        assert_eq!(resp.usage.as_ref().unwrap().total_tokens, Some(102960));
    }
}

