        assert_eq!(cli.args.model, "standard");
    }

    #[test]
    fn parse_multiple_sources_for_bridging() {
        let cli = TestCli::try_parse_from([
            "test",
            "--source-video", "v1.mp4",
            "--source-video", "v2.mp4",
            "--source-video", "v3.mp4",
            "视频1打开门，接视频2，镜头推进，接视频3",
        ])
        .unwrap();
        assert_eq!(cli.args.source_video, vec!["v1.mp4", "v2.mp4", "v3.mp4"]);
    }

    #[test]
    fn parse_with_options() {
        let cli = TestCli::try_parse_from([
            "test",
            "--source-video", "clip.mp4",
            "延长内容",
            "--model", "fast",
            "--duration", "10",
            "--ratio", "9:16",
            "--audio-gen",
            "--return-last-frame",
            "--wait",
        ])
        .unwrap();
        assert_eq!(cli.args.model, "fast");
        assert_eq!(cli.args.duration, 10);
        assert_eq!(cli.args.ratio, "9:16");
        assert!(cli.args.audio_gen);
        assert!(cli.args.return_last_frame);
        assert!(cli.args.wait);
    }

    #[test]
    fn parse_with_image_refs() {
        let cli = TestCli::try_parse_from([
            "test",
            "--source-video", "base.mp4",
            "延长并加入角色",
            "--image", "character.png",
            "--image", "asset://asset-123",
        ])
        .unwrap();
        assert_eq!(cli.args.image.len(), 2);
        assert_eq!(cli.args.image[1], "asset://asset-123");
    }

    #[test]
    fn reject_no_source() {
        let result = TestCli::try_parse_from(["test", "只有prompt没有source"]);
        assert!(result.is_err());
    }

    #[test]
    fn reject_too_many_sources() {
        // clap Append allows 4 values at parse time; validation is runtime-only
        let cli = TestCli::try_parse_from([
            "test",
            "--source-video", "a.mp4",
            "--source-video", "b.mp4",
            "--source-video", "c.mp4",
            "--source-video", "d.mp4",
            "prompt",
        ])
        .unwrap();
        assert_eq!(cli.args.source_video.len(), 4);
    }
}

