        cfg.duration = 12;

        let serialized = toml::to_string_pretty(&cfg).unwrap();
        let deserialized: AppConfig = toml::from_str(&serialized).unwrap();

        assert_eq!(deserialized.api_key, Some("sk-roundtrip".into()));
