use anyhow::{Context, Result};
use hmac::{Hmac, Mac};
use sha2::{Digest, Sha256};
use std::env;
use std::path::Path;

type HmacSha256 = Hmac<Sha256>;

fn hmac_sign(key: &[u8], msg: &[u8]) -> Vec<u8> {
    let mut mac = HmacSha256::new_from_slice(key).expect("HMAC key size");
    mac.update(msg);
    mac.finalize().into_bytes().to_vec()
}

fn sha256_hex(data: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(data);
    hex::encode(hasher.finalize())
}

fn get_env(name: &str) -> Result<String> {
    env::var(name).with_context(|| format!("environment variable {name} is not set"))
}

/// Upload a file to TOS (S3-compatible) and return the public HTTPS URL.
///
/// Required env vars:
///   TOS_ACCESS_KEY — Access Key ID
///   TOS_SECRET_KEY — Secret Access Key
///   TOS_BUCKET     — Bucket name
/// Optional:
///   TOS_ENDPOINT   — default: tos-cn-beijing.volces.com
///   TOS_REGION     — default: cn-beijing
pub async fn upload_file(file_path: &str) -> Result<String> {
    let access_key = get_env("TOS_ACCESS_KEY")?;
    let secret_key = get_env("TOS_SECRET_KEY")?;
    let bucket = get_env("TOS_BUCKET")?;
    let region = env::var("TOS_REGION").unwrap_or_else(|_| "cn-beijing".into());
    let endpoint = env::var("TOS_ENDPOINT").unwrap_or_else(|_| "tos-s3-cn-beijing.volces.com".into());

    // Read file
    let data = tokio::fs::read(file_path)
        .await
        .with_context(|| format!("failed to read {file_path}"))?;

    let filename = Path::new(file_path)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("video.mp4");

    let content_type = if filename.ends_with(".mp4") {
        "video/mp4"
    } else if filename.ends_with(".mov") {
        "video/quicktime"
    } else {
        "application/octet-stream"
    };

    // Object key: seedance-cli/{timestamp}_{uuid}_{filename}
    let now = chrono::Utc::now();
    let ts = now.format("%Y%m%dT%H%M%S").to_string();
    let id = uuid::Uuid::new_v4().to_string().split('-').next().unwrap().to_string();
    let key = format!("seedance-cli/{ts}_{id}_{filename}");

    let amz_date = now.format("%Y%m%dT%H%M%SZ").to_string();
    let date_stamp = now.format("%Y%m%d").to_string();
    let content_sha256 = sha256_hex(&data);
    let service = "s3";

    // Virtual-hosted style: {bucket}.{endpoint}
    let host = format!("{bucket}.{endpoint}");
    let canonical_uri = format!("/{key}");
    let canonical_querystring = "";

    // 8-hour auto-expiry
    let expires_at = (now + chrono::Duration::hours(8))
        .format("%Y-%m-%dT%H:%M:%SZ")
        .to_string();

    let canonical_headers = format!(
        "content-type:{content_type}\nhost:{host}\nx-amz-content-sha256:{content_sha256}\nx-amz-date:{amz_date}\nx-amz-meta-expire-at:{expires_at}\n"
    );
    let signed_headers = "content-type;host;x-amz-content-sha256;x-amz-date;x-amz-meta-expire-at";

    let canonical_request = format!(
        "PUT\n{canonical_uri}\n{canonical_querystring}\n{canonical_headers}\n{signed_headers}\n{content_sha256}"
    );

    // String to Sign
    let credential_scope = format!("{date_stamp}/{region}/{service}/aws4_request");
    let string_to_sign = format!(
        "AWS4-HMAC-SHA256\n{amz_date}\n{credential_scope}\n{}",
        sha256_hex(canonical_request.as_bytes())
    );

    // Signing key
    let date_key = hmac_sign(format!("AWS4{secret_key}").as_bytes(), date_stamp.as_bytes());
    let region_key = hmac_sign(&date_key, region.as_bytes());
    let service_key = hmac_sign(&region_key, service.as_bytes());
    let signing_key = hmac_sign(&service_key, b"aws4_request");

    let signature = hex::encode(hmac_sign(&signing_key, string_to_sign.as_bytes()));

    let authorization = format!(
        "AWS4-HMAC-SHA256 Credential={access_key}/{credential_scope}, SignedHeaders={signed_headers}, Signature={signature}"
    );

    // ── Send PUT request ──

    let url = format!("https://{host}{canonical_uri}");
    let host_header = host.clone();

    let client = reqwest::Client::new();
    let resp = client
        .put(&url)
        .header("Host", &host_header)
        .header("x-amz-date", &amz_date)
        .header("x-amz-content-sha256", &content_sha256)
        .header("Content-Type", content_type)
        .header("x-amz-meta-expire-at", &expires_at)
        .header("Authorization", &authorization)
        .body(data)
        .send()
        .await
        .context("failed to upload to TOS")?;

    let status = resp.status();
    if !status.is_success() {
        let body = resp.text().await.unwrap_or_default();
        anyhow::bail!("TOS upload failed (HTTP {status}): {body}");
    }

    // Public URL: https://{bucket}.{endpoint}/{key}
    let public_url = format!("https://{host_header}/{key}");
    Ok(public_url)
}

/// Delete a file from TOS by its public URL.
///
/// Parses the key from the URL, sends a SigV4-signed DELETE request.
pub async fn delete_file(public_url: &str) -> Result<()> {
    let access_key = get_env("TOS_ACCESS_KEY")?;
    let secret_key = get_env("TOS_SECRET_KEY")?;
    let bucket = get_env("TOS_BUCKET")?;
    let region = env::var("TOS_REGION").unwrap_or_else(|_| "cn-beijing".into());
    let endpoint = env::var("TOS_ENDPOINT").unwrap_or_else(|_| "tos-s3-cn-beijing.volces.com".into());

    let host = format!("{bucket}.{endpoint}");
    let prefix = format!("https://{host}/");
    let key = public_url
        .strip_prefix(&prefix)
        .with_context(|| format!("cannot extract TOS key from URL: {public_url}"))?;

    let now = chrono::Utc::now();
    let amz_date = now.format("%Y%m%dT%H%M%SZ").to_string();
    let date_stamp = now.format("%Y%m%d").to_string();
    let payload_hash = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";

    let canonical_uri = format!("/{key}");
    let canonical_headers = format!(
        "host:{host}\nx-amz-content-sha256:{payload_hash}\nx-amz-date:{amz_date}\n"
    );
    let signed_headers = "host;x-amz-content-sha256;x-amz-date";
    let canonical_request = format!(
        "DELETE\n{canonical_uri}\n\n{canonical_headers}\n{signed_headers}\n{payload_hash}"
    );

    let service = "s3";
    let credential_scope = format!("{date_stamp}/{region}/{service}/aws4_request");
    let string_to_sign = format!(
        "AWS4-HMAC-SHA256\n{amz_date}\n{credential_scope}\n{}",
        sha256_hex(canonical_request.as_bytes())
    );

    let date_key = hmac_sign(format!("AWS4{secret_key}").as_bytes(), date_stamp.as_bytes());
    let region_key = hmac_sign(&date_key, region.as_bytes());
    let service_key = hmac_sign(&region_key, service.as_bytes());
    let signing_key = hmac_sign(&service_key, b"aws4_request");
    let signature = hex::encode(hmac_sign(&signing_key, string_to_sign.as_bytes()));

    let authorization = format!(
        "AWS4-HMAC-SHA256 Credential={access_key}/{credential_scope}, SignedHeaders={signed_headers}, Signature={signature}"
    );

    let url = format!("https://{host}{canonical_uri}");
    let client = reqwest::Client::new();
    let resp = client
        .delete(&url)
        .header("Host", &host)
        .header("x-amz-date", &amz_date)
        .header("x-amz-content-sha256", payload_hash)
        .header("Authorization", &authorization)
        .send()
        .await
        .context("failed to delete from TOS")?;

    let status = resp.status();
    if status != 204 && status != 404 {
        let body = resp.text().await.unwrap_or_default();
        anyhow::bail!("TOS delete failed (HTTP {status}): {body}");
    }
    Ok(())
}

/// Clean up all expired objects under `seedance-cli/` prefix.
///
/// Object keys contain a timestamp: `seedance-cli/{timestamp}_{uuid}_{filename}`.
/// Objects older than 8 hours are deleted.
pub async fn cleanup_expired() -> Result<usize> {
    let access_key = get_env("TOS_ACCESS_KEY")?;
    let secret_key = get_env("TOS_SECRET_KEY")?;
    let bucket = get_env("TOS_BUCKET")?;
    let region = env::var("TOS_REGION").unwrap_or_else(|_| "cn-beijing".into());
    let endpoint = env::var("TOS_ENDPOINT").unwrap_or_else(|_| "tos-s3-cn-beijing.volces.com".into());
    let service = "s3";
    let host = format!("{bucket}.{endpoint}");
    let prefix = "seedance-cli/";

    let now = chrono::Utc::now();
    let cutoff = now - chrono::Duration::hours(8);
    let amz_date = now.format("%Y%m%dT%H%M%SZ").to_string();
    let date_stamp = now.format("%Y%m%d").to_string();
    let payload_hash = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";

    // List objects
    let canonical_uri = "/";
    let canonical_querystring = format!("prefix={prefix}");
    let canonical_headers = format!(
        "host:{host}\nx-amz-content-sha256:{payload_hash}\nx-amz-date:{amz_date}\n"
    );
    let signed_headers = "host;x-amz-content-sha256;x-amz-date";
    let canonical_request = format!(
        "GET\n{canonical_uri}\n{canonical_querystring}\n{canonical_headers}\n{signed_headers}\n{payload_hash}"
    );

    let credential_scope = format!("{date_stamp}/{region}/{service}/aws4_request");
    let string_to_sign = format!(
        "AWS4-HMAC-SHA256\n{amz_date}\n{credential_scope}\n{}",
        sha256_hex(canonical_request.as_bytes())
    );

    let date_key = hmac_sign(format!("AWS4{secret_key}").as_bytes(), date_stamp.as_bytes());
    let region_key = hmac_sign(&date_key, region.as_bytes());
    let service_key = hmac_sign(&region_key, service.as_bytes());
    let signing_key = hmac_sign(&service_key, b"aws4_request");
    let signature = hex::encode(hmac_sign(&signing_key, string_to_sign.as_bytes()));

    let authorization = format!(
        "AWS4-HMAC-SHA256 Credential={access_key}/{credential_scope}, SignedHeaders={signed_headers}, Signature={signature}"
    );

    let list_url = format!("https://{host}/?prefix={prefix}");
    let client = reqwest::Client::new();
    let resp = client
        .get(&list_url)
        .header("Host", &host)
        .header("x-amz-date", &amz_date)
        .header("x-amz-content-sha256", payload_hash)
        .header("Authorization", &authorization)
        .send()
        .await
        .context("failed to list TOS objects")?;

    let body = resp.text().await.context("failed to read TOS list response")?;

    // Parse XML keys and extract timestamps
    let mut deleted = 0;
    let mut in_key = false;
    for line in body.lines() {
        let trimmed = line.trim();
        if trimmed == "<Key>" {
            in_key = true;
        } else if trimmed == "</Key>" {
            in_key = false;
        } else if in_key {
            let key = trimmed.to_string();
            // Key format: seedance-cli/{timestamp}_{...}
            if let Some(rest) = key.strip_prefix("seedance-cli/") {
                // timestamp is 15 chars: YYYYMMDDTHHMMSS
                if rest.len() >= 15 {
                    let ts_str = &rest[..15];
                    let key_dt = chrono::NaiveDateTime::parse_from_str(ts_str, "%Y%m%dT%H%M%S")
                        .map(|dt| chrono::DateTime::<chrono::Utc>::from_naive_utc_and_offset(dt, chrono::Utc));
                    if let Ok(dt) = key_dt {
                        if dt < cutoff {
                            if delete_file(&format!("https://{host}/{key}")).await.is_ok() {
                                deleted += 1;
                            }
                        }
                    }
                }
            }
        }
    }

    Ok(deleted)
}

use anyhow::{Context, Result};
use std::process::Command;

use super::tos;

/// Probe the duration of a video file in seconds using ffprobe.
pub fn probe_duration(path: &str) -> Result<f64> {
    let output = Command::new("ffprobe")
        .args([
            "-v",
            "error",
            "-show_entries",
            "format=duration",
            "-of",
            "csv=p=0",
            path,
        ])
        .output()
        .context("failed to run ffprobe — is ffmpeg installed? (brew install ffmpeg)")?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        anyhow::bail!("ffprobe failed: {stderr}");
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let duration_str = stdout.trim();
    duration_str
        .parse::<f64>()
        .with_context(|| format!("failed to parse ffprobe duration output: '{duration_str}'"))
}

/// Trim a video from the end, keeping the last `keep_secs` seconds.
/// Uses re-encode to ensure clean keyframes (stream copy can produce corrupted mp4).
pub fn trim_from_end(input: &str, output: &str, keep_secs: f64) -> Result<()> {
    let total = probe_duration(input)?;
    let start = (total - keep_secs).max(0.0);

    let result = Command::new("ffmpeg")
        .args([
            "-y",
            "-ss",
            &format!("{start}"),
            "-i",
            input,
            "-t",
            &format!("{keep_secs}"),
            "-c:v",
            "libx264",
            "-preset",
            "fast",
            "-crf",
            "23",
            "-c:a",
            "aac",
            output,
        ])
        .output()
        .context("failed to run ffmpeg — is ffmpeg installed? (brew install ffmpeg)")?;

    if !result.status.success() {
        let stderr = String::from_utf8_lossy(&result.stderr);
        anyhow::bail!("ffmpeg trim failed: {stderr}");
    }

    Ok(())
}

/// Prepare a source video for extend: probe duration, trim if too long, upload to TOS.
///
/// If the input is already an HTTP(S)/asset URL, it is returned as-is.
/// Local files are probed, trimmed if they exceed `max_duration` seconds,
/// then uploaded to TOS (S3-compatible) to get a public HTTPS URL.
///
/// Requires TOS_ACCESS_KEY, TOS_SECRET_KEY, TOS_BUCKET env vars for local files.
pub async fn prepare_source_video(input: &str, max_duration: u8) -> Result<String> {
    // URLs are passed through directly
    if input.starts_with("http://") || input.starts_with("https://") || input.starts_with("asset://") {
        return Ok(input.to_string());
    }

    let duration = probe_duration(input)?;

    if duration <= max_duration as f64 {
        // Upload as-is to TOS
        return tos::upload_file(input).await;
    }

    // Trim: keep the last max_duration seconds, then upload
    let trimmed_path = format!("{input}.seedance_trimmed.mp4");
    trim_from_end(input, &trimmed_path, max_duration as f64)?;

    let url = tos::upload_file(&trimmed_path).await;

    // Clean up temp file (best-effort)
    let _ = std::fs::remove_file(&trimmed_path);

    url
}

mod cli;
mod client;
mod config;
mod core;
mod store;
mod ui;

use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(
    name = "seedance",
    about = "CLI for Seedance 2.0 video generation on Volcengine Ark",
    version
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Create a video generation task (T2V / I2V / V2V / R2V)
    Generate(cli::generate::GenerateArgs),

    /// Extend a video forward/backward, or bridge multiple clips
    Extend(cli::extend::ExtendArgs),

    /// Edit an existing video (replace, add, remove, repaint)
    Edit(cli::edit::EditArgs),

    /// Query task status
    Status(cli::status::StatusArgs),

    /// Download a completed video
    Download(cli::download::DownloadArgs),

    /// List task history
    List(cli::list::ListArgs),

    /// Clean up expired TOS temporary files
    Cleanup,

    /// Manage configuration
    Config {
        #[command(subcommand)]
        command: cli::config::ConfigCommand,
    },
}

#[tokio::main]
async fn main() {
    let cli = Cli::parse();

    let result = match cli.command {
        Commands::Generate(args) => cli::generate::execute(args).await,
        Commands::Extend(args) => cli::extend::execute(args).await,
        Commands::Edit(args) => cli::edit::execute(args).await,
        Commands::Status(args) => cli::status::execute(args).await,
        Commands::Download(args) => cli::download::execute(args).await,
        Commands::List(args) => cli::list::execute(args).await,
        Commands::Cleanup => cli::cleanup::execute().await,
        Commands::Config { command } => cli::config::execute(command).await,
    };

    if let Err(e) = result {
        ui::print_error(&format!("{e:#}"));
        std::process::exit(1);
    }
}

