            wait: false,
            output: None,
            timeout: 300,
            poll_interval: 10,
            strict: false,
            quiet: false,
            json: false,
        }
    }

    #[test]
    fn resolve_model_id_standard() {
        assert_eq!(
            resolve_model_id("standard"),
            "doubao-seedance-2-0-260128"
        );
    }

