            first_frame: None,
            last_frame: None,
            wait: false,
            output: None,
            timeout: 300,
            poll_interval: 10,
            strict: false,
            quiet: false,
            json: false,
        }
    }

    #[test]
    fn resolve_model_id_standard() {
        assert_eq!(
            resolve_model_id("standard"),
            "doubao-seedance-2-0-260128"
        );
    }

    #[test]
    fn resolve_model_id_std_alias() {
