            "--source-video", "a.mp4",
            "--source-video", "b.mp4",
            "--source-video", "c.mp4",
            "--source-video", "d.mp4",
            "prompt",
        ])
        .unwrap();
        assert_eq!(cli.args.source_video.len(), 4);
    }
}

