        store.insert("cgt-020", "prompt a", "standard").unwrap();
        store.insert("cgt-021", "prompt b", "standard").unwrap();
        store.update_status("cgt-020", "succeeded", None).unwrap();

        let all = store.list(10, Some("all")).unwrap();
        assert_eq!(all.len(), 2);
    }

